import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StreamTokenizer st = new StreamTokenizer(br);
        st.nextToken();
        int N = (int) st.nval;
        st.nextToken();
        int M = (int) st.nval;
        int[] t = new int[M];
        for (int i = 0; i < M; i++) {
            st.nextToken();
            t[i] = (int) st.nval;
        }

        // Total de sobreviventes: aplica f(y) = y - floor(y/t) sequencialmente a partir de N
        long total = N;
        for (int i = 0; i < M; i++) {
            total -= total / t[i];
        }

        int K = (int) Math.min(total, 10000L);

        StringBuilder sb = new StringBuilder();
        for (int k = 1; k <= K; k++) {
            // Encontra o menor x tal que f_M(x) >= k, invertendo cada turno de tras para frente.
            // Inversa de g(y) = y - floor(y/t): menor y com g(y) >= z  =>  y = z + q,
            // onde q = floor((z-t)/(t-1)) + 1  (q = floor(y/t) satisfaz (t-1)q <= z < (t-1)q + t).
            long w = k;
            for (int i = M - 1; i >= 0; i--) {
                long ti = t[i];
                w += Math.floorDiv(w - ti, ti - 1) + 1;
            }
            sb.append(w).append('\n');
        }
        System.out.print(sb);
    }
}
